from pathlib import Path
import tomllib, json, datetime

base_path = Path('/config/base.toml')
env_dir = Path('/config/env')
out_dir = Path('/out')
out_dir.mkdir(parents=True, exist_ok=True)
base = tomllib.loads(base_path.read_text(encoding='utf-8'))

def merge(base, override):
    result = dict(base)
    for key, value in override.items():
        if value == '__unset__' and isinstance(value, str):
            result.pop(key, None)
        elif key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = value
    return result

def convert(value):
    if isinstance(value, dict):
        return {key: convert(item) for key, item in value.items()}
    if isinstance(value, list):
        return [convert(item) for item in value]
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    return value

environments = sorted(env_dir.glob('*.toml'), key=lambda p: p.stem)
names = []
for path in environments:
    name = path.stem
    names.append(name)
    override = tomllib.loads(path.read_text(encoding='utf-8'))
    rendered = convert(merge(base, override))
    (out_dir / f'{name}.json').write_text(json.dumps(rendered, indent=2, sort_keys=True, ensure_ascii=False) + '\n', encoding='utf-8')
(out_dir / 'index.txt').write_text(''.join(name + '\n' for name in names), encoding='utf-8')
